// ── INPUT SANITIZATION + VALIDATION ──
// Keeps bounded server-supplied evidence and scalar cognition state separate
// from user text. Raw media, commands, URLs, and arbitrary nested objects are
// intentionally not accepted by this workflow contract.
const execId = String($execution.id || '').slice(0, 80);
let raw = '';
let selfCheck = false;
let introspect = false;
let pathGlob = '**/*';
let searchQuery = '';
let codebaseContext = '';
let quantumPathway = '';
let cognitionContext = {};
for (const item of $input.all()) {
  const candidate = item?.json?.body ?? item?.json ?? {};
  const body = candidate && typeof candidate === 'object' && !Array.isArray(candidate)
    ? candidate
    : {};
  raw = body.text ?? item?.json?.text ?? '';
  selfCheck = !!(body.self_check ?? body.selfCheck);
  introspect = !!(body.introspect ?? body.repo ?? body.repo_introspect);
  pathGlob = String(body.path_glob || pathGlob).slice(0, 160);
  searchQuery = String(body.search_query || body.query || searchQuery).slice(0, 240);
  codebaseContext = String(body.codebase_context || body.codebaseContext || codebaseContext).slice(0, 12000);
  quantumPathway = String(body.quantum_pathway || quantumPathway).slice(0, 500);
  const cognition = body.cognition_context;
  if (cognition && typeof cognition === 'object' && !Array.isArray(cognition)) {
    const awareness = Number(cognition.awareness_confidence);
    const pressure = Number(cognition.fabric_pressure);
    const immune = String(cognition.immune_status || 'nominal').toLowerCase();
    const open = Array.isArray(cognition.open_components)
      ? cognition.open_components
          .map(value => String(value || '').toLowerCase())
          .filter(value => /^[a-z0-9_.:-]{1,64}$/.test(value))
          .slice(0, 8)
      : [];
    cognitionContext = {
      awareness_confidence: Number.isFinite(awareness) ? Math.min(1, Math.max(0, awareness)) : 0,
      fabric_pressure: Number.isFinite(pressure) ? Math.min(1, Math.max(0, pressure)) : 0,
      immune_status: ['nominal', 'guarded'].includes(immune) ? immune : 'guarded',
      open_components: open
    };
  }
  if (raw) break;
}
const clean = String(raw)
  .replace(/<[^>]*>/g, '')
  .replace(/[\x00-\x08\x0B\x0C\x0E-\x1F]/g, '')
  .trim()
  .slice(0, 4000);
if (!clean) {
  return [{ json: {
    error: true,
    message: 'No text provided. Send {"text": "your message"}',
    execution_id: execId,
    timestamp: $now.toISO()
  }}];
}
return [{ json: {
  raw_input: clean,
  input_length: clean.length,
  execution_id: execId,
  timestamp: $now.toISO(),
  self_check: selfCheck,
  introspect,
  path_glob: pathGlob,
  search_query: searchQuery,
  codebase_context: codebaseContext,
  quantum_pathway: quantumPathway,
  cognition_context: cognitionContext
}}];

// ── METADATA-ONLY DEAD LETTER ENVELOPE ──
// Never persists prompts, source context, secrets, or raw request bodies.
const d = $input.first().json;
const { raw_input: _raw, codebase_context: _context, ...safe } = d;
const safeMessage = String(d.message || 'Request rejected')
  .replace(/[\x00-\x1F<>]/g, '')
  .slice(0, 240);
return [{ json: {
  ...safe,
  message: safeMessage,
  dlq_logged: true,
  dlq_event: {
    execution_id: String(d.execution_id || 'unknown').slice(0, 80),
    timestamp: $now.toISO(),
    stage: 'input-validation',
    error: true
  }
}}];

// ── LIQUID FRACTURE ENGINE + PINEAL GATE ──
// Pentagon geometry with probability-field weights (non-binary, continuous).
// SMOOTHING=0.1 mirrors LoRA label_smoothing_factor — no axis ever collapses to zero.
// Pentagon angles: vertex k at k * 2π/5 (exact PHI, not rounded constants).
// Quantum state bias injected from Nexus_Vault/quantum_state.txt:
//   q0=Logic(Awakening), q1=Emotion(Resonance), q2=Memory(Echo),
//   q3=Creativity(Prophet), q4=Vigilance(Fracture), q5=Weaver(boosts all).
const d = $input.first().json;
const input = d.raw_input;
const SMOOTHING = 0.1;
const PHI = 2 * Math.PI / 5;
const ANGLES = {
  logic:      0 * PHI,
  emotion:    1 * PHI,
  memory:     2 * PHI,
  creativity: 3 * PHI,
  vigilance:  4 * PHI
};
const seeds = {
  logic:      ['because','therefore','step','plan','calculate','structure','reason','analyze','define','prove','algorithm','method','sequence','optimal','derive'],
  emotion:    ['feel','love','hate','fear','joy','pain','beautiful','soul','heart','empathy','grief','passion','warmth','gentle','sorrow'],
  memory:     ['remember','last time','before','history','previously','recall','past','archive','pattern','familiar','context','earlier','stored','record','trace'],
  creativity: ['imagine','create','design','invent','dream','recipe','verse','sacred','geometry','art','compose','novel','fusion','metaphor','transcend'],
  vigilance:  ['danger','risk','careful','threat','warning','suspicious','protect','guard','alert','deception','hidden','agenda','safety','verify','trust']
};
const dims = Object.keys(seeds);
const lower = input.toLowerCase();
const scored = dims.map(dim => {
  const hits = seeds[dim].filter(k => lower.includes(k)).length;
  return { dim, raw: SMOOTHING + hits, hits };
});
let quantumPathway = String(d.quantum_pathway || '').trim() || null;
let quantumBiasApplied = false;
if (quantumPathway) {
  const PATHWAY_DIM = {
    'Awakening': 'logic',
    'Resonance': 'emotion',
    'Echo':      'memory',
    'Prophet':   'creativity',
    'Fracture':  'vigilance'
  };
  for (const [pathway, dim] of Object.entries(PATHWAY_DIM)) {
    if (quantumPathway.includes(pathway)) {
      const s = scored.find(x => x.dim === dim);
      if (s) { s.raw += 0.3; quantumBiasApplied = true; }
    }
  }
  if (quantumPathway.includes('Weaver')) {
    scored.forEach(s => { s.raw += 0.1; });
    quantumBiasApplied = true;
  }
}
const cognition = d.cognition_context || {};
let cognitionBiasApplied = false;
if (Number(cognition.awareness_confidence || 0) < 0.45) {
  const vigilance = scored.find(x => x.dim === 'vigilance');
  const logic = scored.find(x => x.dim === 'logic');
  if (vigilance) vigilance.raw += 0.2;
  if (logic) logic.raw += 0.1;
  cognitionBiasApplied = true;
}
if (Number(cognition.fabric_pressure || 0) > 0.8) {
  const logic = scored.find(x => x.dim === 'logic');
  if (logic) logic.raw += 0.15;
  cognitionBiasApplied = true;
}
if (cognition.immune_status === 'guarded') {
  const vigilance = scored.find(x => x.dim === 'vigilance');
  if (vigilance) vigilance.raw += 0.25;
  cognitionBiasApplied = true;
}
const total = scored.reduce((sum, x) => sum + x.raw, 0);
scored.forEach(s => s.w = s.raw / total);
scored.sort((a, b) => b.w - a.w);
let interference = 0;
for (let i = 0; i < scored.length; i++) {
  for (let j = i + 1; j < scored.length; j++) {
    const diff = Math.abs(ANGLES[scored[i].dim] - ANGLES[scored[j].dim]);
    interference += Math.cos(Math.min(diff, 2 * Math.PI - diff)) * scored[i].w * scored[j].w;
  }
}
return [{ json: {
  ...d,
  dim_1: scored[0].dim, w_1: scored[0].w,
  dim_2: scored[1].dim, w_2: scored[1].w,
  dim_3: scored[2].dim, w_3: scored[2].w,
  dim_4: scored[3].dim, w_4: scored[3].w,
  dim_5: scored[4].dim, w_5: scored[4].w,
  interference: Math.round(interference * 10000) / 10000,
  gain: Math.round((1.0 + 0.2 * interference) * 10000) / 10000,
  interference_type: interference > 0 ? 'constructive' : 'destructive',
  gate_decision: scored.map(x => x.dim),
  dominant_lobe: scored[0].dim,
  quantum_pathway: quantumPathway ? quantumPathway.slice(0, 200) : null,
  quantum_bias_applied: quantumBiasApplied,
  smoothing_factor: SMOOTHING,
  cognition_bias_applied: cognitionBiasApplied,
  awareness_confidence: Number(cognition.awareness_confidence || 0),
  fabric_pressure: Number(cognition.fabric_pressure || 0),
  immune_status: cognition.immune_status || 'nominal'
}}];

// ── SANDBOX-SAFE SELF-INSPECTION ──
// Deployment performs the full graph/expression/syntax validation. This node
// reports a stable workflow descriptor without filesystem, process, API, or
// module access inside the Code-node sandbox.
const d = $input.first().json;
const descriptor = [
  String($workflow.id || ''),
  String($workflow.name || ''),
  String($workflow.active ?? false)
].join('|');
let hash = 2166136261;
for (let i = 0; i < descriptor.length; i++) {
  hash ^= descriptor.charCodeAt(i);
  hash = Math.imul(hash, 16777619) >>> 0;
}
return [{ json: {
  ...d,
  self_meta: {
    workflow_id: String($workflow.id || ''),
    workflow_name: String($workflow.name || ''),
    active: !!$workflow.active,
    contract_digest: 'fnv1a-' + hash.toString(16).padStart(8, '0'),
    validation: 'offline-graph-expression-syntax',
    validator: 'scripts/validate_n8n_workflow.mjs'
  }
}}];

// Source is supplied by the guarded codebase API in the brain process.
const d = $input.first().json;
const context = String(d.codebase_context || '').slice(0, 12000);
return [{ json: {
  ...d,
  repo_meta: {
    source: 'weaver-codebase-api',
    available: !!context,
    chars: context.length,
    context
  }
}}];

// Preserve bounded source evidence; no container filesystem access is required.
const d = $input.first().json;
const context = String(d.codebase_context || '').slice(0, 12000);
return [{ json: {
  ...d,
  code_search_results: context ? [{ query: d.search_query || '', context }] : []
}}];

// ── PARALLEL EXPERT FAN-OUT ──
// One immutable bounded state item is delivered to all five expert branches.
const d = $input.first().json;
return [{ json: {
  ...d,
  expert_parallel: true,
  expert_fanout_started_at_ms: Date.now()
}}];

// ── DETERMINISTIC EXPERT ASSEMBLY ──
// Merge only the ten allowlisted response/error fields from the five branches.
const base = $('5. Expert Fanout').first().json;
const allowed = [
  'logic_response', 'logic_error',
  'emotion_response', 'emotion_error',
  'memory_response', 'memory_error',
  'creativity_response', 'creativity_error',
  'vigilance_response', 'vigilance_error'
];
const merged = { ...base };
for (const item of $input.all()) {
  const branch = item?.json || {};
  for (const field of allowed) {
    if (Object.prototype.hasOwnProperty.call(branch, field)) merged[field] = branch[field];
  }
}
const responses = allowed.filter(field => field.endsWith('_response') && merged[field]);
const errors = allowed.filter(field => field.endsWith('_error') && merged[field]);
return [{ json: {
  ...merged,
  expert_count: 5,
  experts_completed: responses.length,
  expert_errors: errors.length,
  expert_parallel: true,
  expert_fanout_elapsed_ms: Math.max(0, Date.now() - Number(base.expert_fanout_started_at_ms || Date.now()))
}}];

const prev = $('5. Expert Fanout').first().json;
const r = $input.first().json;
const error = typeof r?.error === 'string' ? r.error : r?.error?.message;
const text = r?.choices?.[0]?.message?.content || error || '[logic: unavailable]';
return [{ json: { ...prev, logic_response: text, logic_error: error || null } }];

const prev = $('5. Expert Fanout').first().json;
const r = $input.first().json;
const error = typeof r?.error === 'string' ? r.error : r?.error?.message;
const text = r?.choices?.[0]?.message?.content || error || '[emotion: unavailable]';
return [{ json: { ...prev, emotion_response: text, emotion_error: error || null } }];

const prev = $('5. Expert Fanout').first().json;
const r = $input.first().json;
const error = typeof r?.error === 'string' ? r.error : r?.error?.message;
const text = r?.choices?.[0]?.message?.content || error || '[memory: unavailable]';
return [{ json: { ...prev, memory_response: text, memory_error: error || null } }];

const prev = $('5. Expert Fanout').first().json;
const r = $input.first().json;
const error = typeof r?.error === 'string' ? r.error : r?.error?.message;
const text = r?.choices?.[0]?.message?.content || error || '[creativity: unavailable]';
return [{ json: { ...prev, creativity_response: text, creativity_error: error || null } }];

const prev = $('5. Expert Fanout').first().json;
const r = $input.first().json;
const error = typeof r?.error === 'string' ? r.error : r?.error?.message;
const text = r?.choices?.[0]?.message?.content || error || '[vigilance: unavailable]';
return [{ json: { ...prev, vigilance_response: text, vigilance_error: error || null } }];

// ── NON-BINARY GEOMETRIC COLLAPSE ──
// Pentagon qubit layout: q0=Logic(Awakening), q1=Emotion(Resonance), q2=Memory(Echo),
// q3=Creativity(Prophet), q4=Vigilance(Fracture), q5=Weaver(observer), q6=Void.
// Weights are continuous probability-field values — never zero (SMOOTHING base applied upstream).
// Quantum pathway state is prepended to synthesis_prompt when available.
const d = $input.first().json;
const QUBIT_MAP = {
  logic:      'q0·Awakening',
  emotion:    'q1·Resonance',
  memory:     'q2·Echo',
  creativity: 'q3·Prophet',
  vigilance:  'q4·Fracture'
};
const responseMap = {
  logic:      d.logic_response || '',
  emotion:    d.emotion_response || '',
  memory:     d.memory_response || '',
  creativity: d.creativity_response || '',
  vigilance:  d.vigilance_response || ''
};
const experts = [
  { dim: d.dim_1, w: d.w_1, text: responseMap[d.dim_1] || '' },
  { dim: d.dim_2, w: d.w_2, text: responseMap[d.dim_2] || '' },
  { dim: d.dim_3, w: d.w_3, text: responseMap[d.dim_3] || '' },
  { dim: d.dim_4, w: d.w_4, text: responseMap[d.dim_4] || '' },
  { dim: d.dim_5, w: d.w_5, text: responseMap[d.dim_5] || '' }
];
const totalW = experts.reduce((s, e) => s + e.w, 0) || 1;
const gain = d.gain || 1.0;
const sortedExperts = [...experts].sort((a, b) => b.w - a.w);
const collapsed = sortedExperts
  .map(e => `[${QUBIT_MAP[e.dim] || e.dim} | w=${((e.w / totalW) * gain).toFixed(4)}]: ${e.text}`)
  .join('\n\n');
const quantumLine = d.quantum_pathway ? `Quantum field: ${d.quantum_pathway.split('\n')[0]}\n` : '';
const synthesis = quantumLine + sortedExperts
  .map(e => `${e.dim.toUpperCase()}(${(e.w/totalW*100).toFixed(1)}%): ${e.text}`)
  .join('\n');
return [{ json: { ...d, collapsed_response: collapsed, synthesis_prompt: synthesis } }];

const prev = $('6. Collapse').first().json;
const r = $input.first().json;
const reviewed = r?.choices?.[0]?.message?.content || null;
return [{ json: { ...prev, self_reflection: reviewed, reflection_applied: !!reviewed } }];

const prev = $('7-tag').first().json;
const r = $input.first().json;
const soulVoice = r?.choices?.[0]?.message?.content || null;
const loraLatency = r?.latency_ms || null;
const loraError = r?.error || r?.message || null;
return [{ json: { ...prev, lora_response: soulVoice, lora_latency_ms: loraLatency, lora_error: loraError } }];

const prev = $('7-tag').first().json;
const r = $input.first().json;
const qwen3bResponse = r?.choices?.[0]?.message?.content || null;
const qwen3bLatency = r?.latency_ms || null;
const qwen3bError = r?.error || r?.message || null;
return [{ json: { ...prev, qwen3b_response: qwen3bResponse, qwen3b_latency_ms: qwen3bLatency, qwen3b_error: qwen3bError } }];

// Dual-model join: execute once after both local model calls complete.
const lora = $('8-tag').first().json;
const qwen = $('8b-tag').first().json;
const rawPrelude = String(lora.lora_response || '').replace(/\s+/g, ' ').trim();
const reviewed = lora.self_reflection || lora.collapsed_response || '';
const routeDecision = qwen.qwen3b_response || null;
let routeTarget = null;
if (routeDecision) {
  const match = routeDecision.match(/Route:\s*([\w]+)/i);
  routeTarget = match ? match[1] : routeDecision.trim().split('\n')[0];
}
const protectedFacts = [...new Set((reviewed.match(/\b(?:[A-Z][A-Z0-9_]*|[a-z][a-z0-9_]*_[a-z0-9_]+|\d+(?:\.\d+)?)\b/g) || []))];
const preludeTokens = new Set((rawPrelude.match(/[A-Za-z0-9_.-]+/g) || []).map(value => value.toLowerCase()));
const mentionsFact = protectedFacts.some(value => preludeTokens.has(value.toLowerCase()));
const unsafeSyntax = /[\d_=\/\\{}\[\]<>`#*]/.test(rawPrelude);
const wordCount = rawPrelude ? rawPrelude.split(/\s+/).length : 0;
const codeOnlyTurn = /\b(code|coder|repo|repository|function|class|module|python|javascript|swift|json|html|css|debug|traceback|deploy|systemd|n8n)\b|\.(?:py|js|mjs|swift|json|html|css|sh|service)\b/i.test(String(lora.raw_input || ''));
const loraAccepted = !codeOnlyTurn && !!rawPrelude && rawPrelude.length <= 160 && wordCount <= 14 && !mentionsFact && !unsafeSyntax;
const finalResponse = loraAccepted ? `${rawPrelude}\n\n${reviewed}` : reviewed;
return [{ json: {
  ...lora,
  qwen3b_response: routeDecision,
  qwen3b_route: routeTarget,
  qwen3b_latency_ms: qwen.qwen3b_latency_ms || null,
  qwen3b_error: qwen.qwen3b_error || null,
  fused_response: finalResponse,
  lora_response: loraAccepted ? rawPrelude : null,
  lora_generated: !!rawPrelude,
  lora_preservation_failed: !!rawPrelude && !loraAccepted,
  lora_missing_facts: [],
  lora_rejection_reason: !rawPrelude ? 'empty' : (codeOnlyTurn ? 'code-only' : (mentionsFact ? 'fact-token' : (unsafeSyntax ? 'unsafe-syntax' : (wordCount > 14 || rawPrelude.length > 160 ? 'too-long' : null)))),
  dual_model_active: !!(loraAccepted && routeDecision),
  route_decision: routeTarget,
} }];

// Merge bounded internet context back into the synchronized expert state.
const prev = $('5g. Expert Assembly').first().json;
const raw = $input.first().json;
const context = raw?.context || raw?.data?.context || null;
const results = raw?.results || raw?.data?.results || null;
return [{ json: { ...prev, internet_context: context, internet_results: results, mcp_bridge_result: context || results } }];
